import React, { useState, useEffect } from 'react';
import Swal from 'sweetalert2';
import Navigation from '../Navigation';
import { Trash2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const TrainNode = class {
  constructor(value, isDamaged = false) {
    this.value = value;
    this.next = null;
    this.isDamaged = isDamaged;
  }
};

const LinkedlistGame = () => {
  const [trainList, setTrainList] = useState(null);
  const [availableCarriages, setAvailableCarriages] = useState([2, 3, 5, 6, 7]);
  const [selectedCarriage, setSelectedCarriage] = useState(null);
  const [gameLevel, setGameLevel] = useState(0);
  const [pointer, setPointer] = useState(null);
  const [insertingNode, setInsertingNode] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [showPointerAnimation, setShowPointerAnimation] = useState(false);
  const [removingNode, setRemovingNode] = useState(null);
  const [prevPointer, setPrevPointer] = useState(null);
  const navigate = useNavigate();
  const [animationStep, setAnimationStep] = useState(0);
  const [showLinkAnimation, setShowLinkAnimation] = useState(false);

  useEffect(() => {
    showIntroStory();
  }, []);

  const handleNavigation = (path) => {
    navigate(path);
};

  const showIntroStory = async () => {
    await Swal.fire({
      title: 'Oh no!',
      html: 'The train has derailed and broken apart!<br>We need your help to fix it!<br>Can you help reassemble the<br>train carriages in the correct order?',
      icon: 'warning',
      timerProgressBar: true,
      showConfirmButton: true,
      position: 'center'
    });
    startLevel1();
  };

  const startLevel1 = () => {
    const initialTrain = new TrainNode(1);
    initialTrain.next = new TrainNode(4);
    setTrainList(initialTrain);
    setGameLevel(1);
  };

  const startLevel2 = async () => {
    await Swal.fire({
      title: 'Great job!',
      text: 'You successfully reassembled the train! But wait... some carriages are damaged and need to be removed!',
      icon: 'success',
      timer: 2000,
      timerProgressBar: true,
      showConfirmButton: false,
      position: 'center'
    });

    const completeTrain = new TrainNode(1);
    let current = completeTrain;
    [2, 3, 4, 5, 6, 7].forEach(value => {
      current.next = new TrainNode(value, value === 3 || value === 6);
      current = current.next;
    });

    setTrainList(completeTrain);
    setGameLevel(2);
    setAvailableCarriages([]);
  };

  const getTrainArray = (head) => {
    const result = [];
    let current = head;
    while (current) {
      result.push({ value: current.value, isDamaged: current.isDamaged });
      current = current.next;
    }
    return result;
  };

  const isValidInsertion = (selectedValue, newValue) => {
    const trainArray = getTrainArray(trainList);
    const selectedIndex = trainArray.findIndex(node => node.value === selectedValue);

    if (selectedIndex === trainArray.length - 1) {
      return newValue > selectedValue;
    }

    if (selectedIndex !== -1) {
      const nextValue = trainArray[selectedIndex + 1].value;
      return newValue > selectedValue && newValue < nextValue;
    }
    return false;
  };

  const checkLevel1Completion = (head) => {
    const trainArray = getTrainArray(head);
    const values = trainArray.map(node => node.value);
    return JSON.stringify(values) === JSON.stringify([1, 2, 3, 4, 5, 6, 7]);
  };

  const checkLevel2Completion = (head) => {
    const trainArray = getTrainArray(head);
    return !trainArray.some(node => node.isDamaged);
  };

  const showQuickAlert = (title, icon) => {
    Swal.fire({
      title,
      icon,
      timer: 1500,
      showConfirmButton: false,
      position: 'center'
    });
  };

  const insertCarriage = async (value) => {
    if (!selectedCarriage) {
      showQuickAlert('Select a carriage first!', 'warning');
      return;
    }

    if (!isValidInsertion(selectedCarriage, value)) {
      showQuickAlert(`Carriage ${value} cannot be placed here!`, 'error');
      return;
    }

    const trainArray = getTrainArray(trainList);
    const selectedIndex = trainArray.findIndex(node => node.value === selectedCarriage);

    setInsertingNode(value);
    setPointer(selectedIndex);
    setAnimationStep(1);

    await new Promise(resolve => setTimeout(resolve, 1000));

    setShowPointerAnimation(true);
    setAnimationStep(2);

    await new Promise(resolve => setTimeout(resolve, 1000));

    setShowLinkAnimation(true);
    setAnimationStep(3);

    await new Promise(resolve => setTimeout(resolve, 1000));

    const newTrain = { ...trainList };
    let current = newTrain;
    while (current && current.value !== selectedCarriage) {
      current = current.next;
    }

    if (current) {
      const newNode = new TrainNode(value);
      newNode.next = current.next;
      current.next = newNode;

      setTrainList(newTrain);
      setAvailableCarriages(availableCarriages.filter(c => c !== value));
      setSelectedCarriage(null);
      setPointer(null);
      setInsertingNode(null);
      setShowPointerAnimation(false);
      setShowLinkAnimation(false);
      setAnimationStep(0);

      if (checkLevel1Completion(newTrain)) {
        startLevel2();
      }
    }
  };

  const removeCarriage = async (value, isDamaged) => {
    if (!value) {
      showQuickAlert('Select a damaged carriage first!', 'warning');
      return;
    }

    if (!isDamaged) {
      showQuickAlert('This carriage is not damaged!', 'error');
      return;
    }

    const trainArray = getTrainArray(trainList);
    const selectedIndex = trainArray.findIndex(node => node.value === value);
    const prevIndex = selectedIndex - 1;

    setRemovingNode(value);
    setPointer(selectedIndex);
    setPrevPointer(prevIndex >= 0 ? prevIndex : null);

    await new Promise(resolve => setTimeout(resolve, 1000));
    setShowPointerAnimation(true);

    await new Promise(resolve => setTimeout(resolve, 1000));

    let newTrain = { ...trainList };
    let current = newTrain;
    let prev = null;

    while (current && current.value !== value) {
      prev = current;
      current = current.next;
    }

    if (current) {
      if (prev) {
        prev.next = current.next;
      } else {
        newTrain = current.next;
      }

      const finalTrain = prev ? newTrain : current.next;
      setTrainList(finalTrain);
      setSelectedCarriage(null);
      setPointer(null);
      setPrevPointer(null);
      setRemovingNode(null);
      setShowPointerAnimation(false);

      if (checkLevel2Completion(finalTrain)) {
        Swal.fire({
          title: 'Victory!',
          text: 'You have successfully fixed the train! All damaged carriages have been removed.',
          icon: 'success',
          confirmButtonText: 'Return to Hompage',
          position: 'center'
        }).then((result) => {
          if (result.isConfirmed) {
            handleNavigation('/ds');
          }
        });
      }
    }
  };

  return (
    <div className="w-full min-h-screen bg-gradient-to-br from-violet-200 via-pink-200 to-yellow-200 relative overflow-hidden flex items-center justify-center py-8 px-4">
      <div className="absolute inset-0">
        <div className="absolute top-0 left-0 w-36 md:w-72 h-36 md:h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tl"></div>
        <div className="absolute top-0 right-0 w-36 md:w-72 h-36 md:h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tr"></div>
        <div className="absolute bottom-0 left-0 w-36 md:w-72 h-36 md:h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-bl"></div>
        <div className="absolute bottom-0 right-0 w-36 md:w-72 h-36 md:h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-br"></div>
        <div className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 w-48 md:w-96 h-48 md:h-96 bg-yellow-300 rounded-full mix-blend-multiply filter blur-xl opacity-50 animate-pulse"></div>
      </div>
      <div className="relative z-10 w-full max-w-6xl mx-auto">
        <div className="bg-white bg-opacity-90 backdrop-blur-lg rounded-2xl shadow-2xl p-4 md:p-8 w-full" style={{border:'3px solid black'}}>
        <div className="flex justify-center items-center gap-5 mb-6"> 
          <h1 className="text-xl md:text-3xl font-bold text-black">
            {gameLevel === 1 ? 'Reassemble the Train' : 'Remove Damaged Carriages'}
          </h1>
          <button 
            className="text-2xl text-indigo-900 hover:bg-indigo-100 rounded p-1"
            onClick={() => setShowModal(true)}
          >
            ℹ️
          </button>
          </div>

          <div className="relative mb-8 md:mb-16 overflow-x-auto">
            <div className="flex gap-2 md:gap-4 justify-start items-center min-w-max px-2 md:px-4">
              {trainList && getTrainArray(trainList).map(({ value, isDamaged }, index) => (
                <div key={index} className="relative h-40 md:h-80" style={{marginTop:'20px'}}>
                  <div
                    onClick={() => setSelectedCarriage(value)}
                    className={`relative group flex items-center justify-center w-16 md:w-28 h-12 md:h-20 
                      ${isDamaged ? 'bg-red-500' : selectedCarriage === value ? 'ring-4 ring-yellow-400 bg-blue-600' : 'bg-blue-500'} 
                      rounded-lg cursor-pointer shadow-lg transition-all duration-300 hover:scale-105`}
                  >
                    <div className={`absolute -left-2 md:-left-4 w-3 md:w-6 h-6 md:h-10 ${isDamaged ? 'bg-red-700' : 'bg-blue-700'} rounded-l-lg`}></div>
                    <div className={`absolute -right-2 md:-right-4 w-3 md:w-6 h-6 md:h-10 ${isDamaged ? 'bg-red-700' : 'bg-blue-700'} rounded-r-lg`}></div>
                    {index < getTrainArray(trainList).length - 1 && (
                      <>
                        <div className={`absolute right-0 w-6 md:w-12 h-1 md:h-2 ${isDamaged ? 'bg-red-700' : 'bg-blue-700'} transform translate-x-full`}></div>
                        <div className={`absolute right-0 w-1 md:w-2 h-2 md:h-4 ${isDamaged ? 'bg-red-700' : 'bg-blue-700'} transform translate-x-[22px] md:translate-x-[44px] -translate-y-1.5 md:-translate-y-3`}></div>
                      </>
                    )}
                    <span className="text-white font-bold text-lg md:text-2xl group-hover:scale-110 transition-transform">
                      {value}
                    </span>
                    {isDamaged && <span className="absolute -top-4 md:-top-6 text-red-600 font-bold text-xs md:text-base">DAMAGED!</span>}
                  </div>

                  {(pointer === index || prevPointer === index) && (
                    <div className="absolute top-16 md:top-24 left-1/2 transform -translate-x-1/2 flex flex-col items-center gap-1 md:gap-2">
                      <div className="text-xl md:text-2xl">👆</div>
                      <div className="text-blue-600 font-mono text-xs md:text-base">
                        {pointer === index ? (showPointerAnimation ? "temp = current.next" : "current") 
                         : prevPointer === index ? (showPointerAnimation ? "prev.next = temp" : "prev") : ""}
                      </div>
                    </div>
                  )}

                  {pointer === index && removingNode && (
                    <div className={`absolute ${showPointerAnimation ? "top-16 md:top-24 left-full transform translate-x-full" : "top-16 md:top-24 left-1/2 transform -translate-x-1/2"} transition-all duration-1000`}>
                      <div className="relative flex items-center justify-center w-16 md:w-28 h-12 md:h-20 bg-red-500 rounded-lg shadow-lg">
                        <div className="absolute -left-2 md:-left-4 w-3 md:w-6 h-6 md:h-10 bg-red-600 rounded-l-lg"></div>
                        <div className="absolute -right-2 md:-right-4 w-3 md:w-6 h-6 md:h-10 bg-red-600 rounded-r-lg"></div>
                        <span className="text-white font-bold text-lg md:text-2xl">{removingNode}</span>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>

          {gameLevel === 1 ? (
            <div className="mb-4 md:mb-8">
              <h2 className="text-lg md:text-xl font-semibold mb-2 md:mb-4 text-gray-700">Available Carriages:</h2>
              <div className="flex gap-2 md:gap-4 justify-center flex-wrap">
                {availableCarriages.map((value) => (
                  <button
                    key={value}
                    onClick={() => insertCarriage(value)}
                    className="px-3 md:px-6 py-2 md:py-3 rounded-lg font-semibold text-base md:text-lg bg-green-500 hover:bg-green-600 hover:shadow-lg active:transform active:scale-95 text-white transition-all duration-200"
                  >
                    Carriage {value}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div className="mb-4 md:mb-8 flex justify-center">
              <button
                onClick={() => removeCarriage(selectedCarriage, trainList && getTrainArray(trainList).find(n => n.value === selectedCarriage)?.isDamaged)}
                className={`px-4 md:px-6 py-2 md:py-3 rounded-lg font-semibold text-base md:text-lg flex items-center gap-2
                  ${selectedCarriage ? 'bg-red-500 hover:bg-red-600' : 'bg-gray-400 cursor-not-allowed'}
                  text-white transition-all duration-200`}
              >
                <Trash2 className="w-5 h-5 md:w-6 md:h-6" />
                Remove Carriage
              </button>
            </div>
          )}
        </div>
        {showModal && (
        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm p-4">
          <div className="bg-white p-6 md:p-8 rounded-2xl max-w-[500px] w-[95%] overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl mb-5 text-indigo-900 text-center font-bold">
              {gameLevel === 1 ? "How to Reassemble the Train" : "How to Fix the Train"}
            </h2>
            
            {gameLevel === 1 ? (
              <>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">1</span>
                  <p className="text-gray-700">Click on an existing carriage where you want to add a new one.</p>
                </div>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">2</span>
                  <p className="text-gray-700">Click on an available carriage button to insert it after your selected carriage.</p>
                </div>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">3</span>
                  <p className="text-gray-700">Carriages must be placed in ascending order (e.g., 1→2→3).</p>
                </div>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">4</span>
                  <p className="text-gray-700">Complete the level by connecting all carriages in order from 1 to 7.</p>
                </div>
              </>
            ) : (
              <>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">1</span>
                  <p className="text-gray-700">Look for damaged carriages marked in red.</p>
                </div>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">2</span>
                  <p className="text-gray-700">Click on a damaged carriage to select it for removal.</p>
                </div>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">3</span>
                  <p className="text-gray-700">Click the 'Remove Carriage' button to remove the selected damaged carriage.</p>
                </div>
                <div className="flex items-center gap-2.5 mb-4">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">4</span>
                  <p className="text-gray-700">Complete the level by removing all damaged carriages.</p>
                </div>
              </>
            )}

            <div className="bg-blue-50 p-4 rounded-lg mt-6 mb-6">
              <h3 className="font-semibold text-indigo-900 mb-2">Tips:</h3>
              <p className="text-gray-700">
                {gameLevel === 1 
                  ? "Watch the connecting animation to understand how carriages link together. You can't place a carriage if it doesn't follow the numerical order." 
                  : "Only damaged carriages (red) can be removed. The train will automatically reconnect after removing a damaged carriage."}
              </p>
            </div>

            <button
              onClick={() => setShowModal(false)}
              className="w-full h-12 bg-indigo-900 text-white text-base font-semibold rounded-lg cursor-pointer flex justify-center items-center transition-all duration-300 hover:bg-indigo-800"
            >
              Got it!
            </button>
          </div>
        </div>
      )}

      </div>
      <style jsx>{`
        @keyframes blob-tl {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(calc(100vw - 9rem), 0) scale(1.1); }
          50% { transform: translate(calc(100vw - 9rem), calc(100vh - 9rem)) scale(1); }
          75% { transform: translate(0, calc(100vh - 9rem)) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-tr {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(0, calc(100vh - 9rem)) scale(1.1); }
          50% { transform: translate(calc(-100vw + 9rem), calc(100vh - 9rem)) scale(1); }
          75% { transform: translate(calc(-100vw + 9rem), 0) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-br {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(calc(-100vw + 9rem), 0) scale(1.1); }
          50% { transform: translate(calc(-100vw + 9rem), calc(-100vh + 9rem)) scale(1); }
          75% { transform: translate(0, calc(-100vh + 9rem)) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-bl {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(0, calc(-100vh + 9rem)) scale(1.1); }
          50% { transform: translate(calc(100vw - 9rem), calc(-100vh + 9rem)) scale(1); }
          75% { transform: translate(calc(100vw - 9rem), 0) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @media (min-width: 768px) {
          @keyframes blob-tl {
            0% { transform: translate(0, 0) scale(1); }
            25% { transform: translate(calc(100vw - 18rem), 0) scale(1.1); }
            50% { transform: translate(calc(100vw - 18rem), calc(100vh - 18rem)) scale(1); }
            75% { transform: translate(0, calc(100vh - 18rem)) scale(0.9); }
            100% { transform: translate(0, 0) scale(1); }
          }
          
          @keyframes blob-tr {
            0% { transform: translate(0, 0) scale(1); }
            25% { transform: translate(0, calc(100vh - 18rem)) scale(1.1); }
            50% { transform: translate(calc(-100vw + 18rem), calc(100vh - 18rem)) scale(1); }
            75% { transform: translate(calc(-100vw + 18rem), 0) scale(0.9); }
            100% { transform: translate(0, 0) scale(1); }
          }
          
          @keyframes blob-br {
            0% { transform: translate(0, 0) scale(1); }
            25% { transform: translate(calc(-100vw + 18rem), 0) scale(1.1); }
            50% { transform: translate(calc(-100vw + 18rem), calc(-100vh + 18rem)) scale(1); }
            75% { transform: translate(0, calc(-100vh + 18rem)) scale(0.9); }
            100% { transform: translate(0, 0) scale(1); }
          }
          
          @keyframes blob-bl {
            0% { transform: translate(0, 0) scale(1); }
            25% { transform: translate(0, calc(-100vh + 18rem)) scale(1.1); }
            50% { transform: translate(calc(100vw - 18rem), calc(-100vh + 18rem)) scale(1); }
            75% { transform: translate(calc(100vw - 18rem), 0) scale(0.9); }
            100% { transform: translate(0, 0) scale(1); }
          }
        }
        
        .animate-blob-tl {
          animation: blob-tl 20s linear infinite;
        }
        
        .animate-blob-tr {
          animation: blob-tr 20s linear infinite;
        }
        
        .animate-blob-bl {
          animation: blob-bl 20s linear infinite;
        }
        
        .animate-blob-br {
          animation: blob-br 20s linear infinite;
        }
        
        .animate-pulse {
          animation: pulse 10s infinite;
        }
        
        @keyframes pulse {
          0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.5; }
          50% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.3; }
        }
      `}</style>
      <Navigation currentPage="linkedlist-game" />
    </div>
  );
};

export default LinkedlistGame;
