import React, { useState, useEffect, useRef } from 'react';
import Swal from 'sweetalert2';
import { useNavigate } from 'react-router-dom';
import Navigation from '../Navigation';

function TreeNode(key) {
    return { left: null, right: null, val: key };
}

const BstGame = () => {
    const [bst, setBst] = useState(null);
    const [traversalMethod, setTraversalMethod] = useState('In-order');
    const [traversalValues, setTraversalValues] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [userInput, setUserInput] = useState('');
    const [showModal, setShowModal] = useState(false);
    const [gameStarted, setGameStarted] = useState(false);
    const [lives, setLives] = useState(3);
    const inputRef = useRef(null);
    const navigate = useNavigate();

    useEffect(() => {
        showIntroStory();
    }, []);

    useEffect(() => {
        if (gameStarted) {
            generateNewTree();
        }
    }, [gameStarted]);

    useEffect(() => {
        if (bst) {
            setTraversalValues(traversal(traversalMethod, bst, []));
            setCurrentIndex(0);
        }
    }, [traversalMethod, bst]);

    useEffect(() => {
        if (gameStarted && inputRef.current) {
            inputRef.current.focus();
        }
    }, [gameStarted, currentIndex]);

    const showIntroStory = async () => {
        const result = await Swal.fire({
            title: 'Welcome to BST Explorer!',
            html: `
                <div class="text-left">
                    <p class="mb-4">🌳 You've discovered an ancient Binary Search Tree containing mysterious numbers!</p>
                    <p class="mb-4">🎯 Your mission: Navigate through the tree using different traversal methods.</p>
                    <p class="mb-4">💫 You have 3 lives to prove your mastery of tree traversal.</p>
                    <p>🏆 Can you achieve the highest score?</p>
                </div>
            `,
            icon: 'info',
            confirmButtonText: 'Start Adventure!',
            showClass: {
                popup: 'animate__animated animate__fadeInDown'
            },
            hideClass: {
                popup: 'animate__animated animate__fadeOutUp'
            },
            didOpen: () => {
                const confirmButton = document.querySelector('.swal2-confirm');
                if (confirmButton) {
                    confirmButton.focus();
                }
            }
        });

        if (result.isConfirmed) {
            setGameStarted(true);
        }
    };

    const handleNavigation = (path) => {
        navigate(path);
    };

    const showVictoryScreen = async (finalScore) => {
        await Swal.fire({
            title: '🎉 Congratulations, Tree Master! 🎉',
            html: `
                <div class="text-center">
                    <p class="mb-4 text-2xl">You've conquered the Binary Search Tree!</p>
                    <p class="mb-4">Final Score: <strong>${finalScore} points</strong></p>
                    <p class="mb-4">You've proven yourself worthy of the title "BST Explorer"!</p>
                </div>
            `,
            icon: 'success',
            confirmButtonText: 'Return to Homepage',
            showClass: {
                popup: 'animate__animated animate__zoomIn'
            },
            didOpen: () => {
                const confirmButton = document.querySelector('.swal2-confirm');
                if (confirmButton) {
                    confirmButton.focus();
                }
            }
        }).then(() => {
            handleNavigation('/ds');
        });
    };

    const showDefeatScreen = async () => {
        await Swal.fire({
            title: 'Game Over!',
            html: `
                <div class="text-center">
                    <p class="mb-4">You've run out of lives!</p>
                    <p class="mb-4">Final Score:<strong> ${score} points</strong></p>
                    <p>Don't give up - try again to master the tree traversal!</p>
                </div>
            `,
            icon: 'error',
            confirmButtonText: 'Return to Homepage',
            showClass: {
                popup: 'animate__animated animate__fadeIn'
            },
            didOpen: () => {
                const confirmButton = document.querySelector('.swal2-confirm');
                if (confirmButton) {
                    confirmButton.focus();
                }
            }
        }).then(() => {
            handleNavigation('/');
        });
    };

    const generateNewTree = () => {
        const numbers = [];
        while (numbers.length < 7) {
            const num = Math.floor(Math.random() * 99) + 1;
            if (!numbers.includes(num)) {
                numbers.push(num);
            }
        }
        numbers.sort((a, b) => a - b);
        let newBst = null;
        const maxHeight = 3;

        const buildRandomTree = (start, end, currentHeight = 1) => {
            if (start > end || currentHeight > maxHeight) return null;
            const mid = Math.floor((start + end) / 2);
            let node = TreeNode(numbers[mid]);
            if (Math.random() > 0.5) {
                node.left = buildRandomTree(start, mid - 1, currentHeight + 1);
            }
            if (Math.random() > 0.5) {
                node.right = buildRandomTree(mid + 1, end, currentHeight + 1);
            }
            return node;
        };

        newBst = buildRandomTree(0, numbers.length - 1);
        if (!newBst) {
            newBst = TreeNode(numbers[0]);
        }
        if (countNodes(newBst) < 8) {
            const requiredNodes = 8 - countNodes(newBst);
            for (let i = 0; i < requiredNodes; i++) {
                const randomNum = Math.floor(Math.random() * 99) + 1;
                if (!numbers.includes(randomNum)) {
                    numbers.push(randomNum);
                    newBst = insert(newBst, randomNum);
                }
            }
        }
        setBst(newBst);
    };

    const countNodes = (node) => {
        if (!node) return 0;
        return 1 + countNodes(node.left) + countNodes(node.right);
    };

    const inOrderTraversal = (node, result) => {
        if (node) {
            inOrderTraversal(node.left, result);
            result.push(node.val);
            inOrderTraversal(node.right, result);
        }
        return result;
    };

    const preOrderTraversal = (node, result) => {
        if (node) {
            result.push(node.val);
            preOrderTraversal(node.left, result);
            preOrderTraversal(node.right, result);
        }
        return result;
    };

    const postOrderTraversal = (node, result) => {
        if (node) {
            postOrderTraversal(node.left, result);
            postOrderTraversal(node.right, result);
            result.push(node.val);
        }
        return result;
    };

    const traversal = (method, root, result) => {
        switch (method) {
            case 'In-order': return inOrderTraversal(root, result);
            case 'Pre-order': return preOrderTraversal(root, result);
            case 'Post-order': return postOrderTraversal(root, result);
            default: return [];
        }
    };

    const insert = (node, key) => {
        if (!node) return TreeNode(key);
        if (key < node.val) {
            node.left = insert(node.left, key);
        } else {
            node.right = insert(node.right, key);
        }
        return node;
    };

    const handleGuess = async () => {
        const guess = parseInt(userInput, 10);
        if (!isNaN(guess)) {
            const correctNextNumber = traversalValues[currentIndex + 1];
            const isLastNumber = currentIndex === traversalValues.length - 2;
            
            if (guess === correctNextNumber) {
                const newScore = score + 10;
                setScore(newScore);

                if (isLastNumber) {
                    await showVictoryScreen(newScore);
                } else {
                    await Swal.fire({
                        title: 'Correct!',
                        text: 'Keep Going ✨💎',
                        icon: 'success',
                        timer: 1500,
                        showConfirmButton: false
                    });
                    setCurrentIndex(currentIndex + 1);
                }
            } else {
                const newLives = lives - 1;
                setLives(newLives);
                
                if (newLives <= 0) {
                    await showDefeatScreen();
                } else {
                    await Swal.fire({
                        title: 'Wrong!',
                        html: `
                            <p>The next number was ${correctNextNumber}</p>
                            <p class="mt-2">Lives remaining: ${newLives}</p>
                        `,
                        icon: 'error',
                        timer: 2000,
                        showConfirmButton: false
                    });
                    setCurrentIndex(currentIndex + 1);
                }
            }
            
            setUserInput('');
            inputRef.current?.focus();
        }
    };

    const renderTree = (node, x, y, dx) => {
        if (!node) return null;
        const levelHeight = 60;
        const nodeRadius = 30;

        return (
            <g key={node.val}>
                <circle cx={x} cy={y} r={nodeRadius} className="fill-cyan-500 stroke-blue-500 stroke-2 cursor-pointer" />
                <text x={x} y={y} textAnchor="middle" className="fill-white text-lg font-bold" dy=".3em">{node.val}</text>
                {node.left && (
                    <g>
                        <line 
                            x1={x - nodeRadius * Math.cos(Math.PI / 8)} 
                            y1={y + nodeRadius * Math.sin(Math.PI / 8)} 
                            x2={x - dx * 0.8} 
                            y2={y + levelHeight - nodeRadius * 0.8} 
                            className="stroke-blue-500 stroke-2"
                        />
                        {renderTree(node.left, x - dx * 0.8, y + levelHeight, dx / 1.8)}
                    </g>
                )}
                {node.right && (
                    <g>
                        <line 
                            x1={x + nodeRadius * Math.cos(Math.PI / 8)} 
                            y1={y + nodeRadius * Math.sin(Math.PI / 8)} 
                            x2={x + dx * 0.8} 
                            y2={y + levelHeight - nodeRadius * 0.8} 
                            className="stroke-blue-500 stroke-2"
                        />
                        {renderTree(node.right, x + dx * 0.8, y + levelHeight, dx / 1.8)}
                    </g>
                )}
            </g>
        );
    };

    return (
        <div className="App min-h-screen w-full bg-gradient-to-br from-violet-200 via-pink-200 to-yellow-200 relative overflow-hidden">
            <div className="absolute inset-0">
                <div className="absolute top-0 left-0 w-72 h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-[blob-tl_20s_linear_infinite]"></div>
                <div className="absolute top-0 right-0 w-72 h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-[blob-tr_20s_linear_infinite]"></div>
                <div className="absolute bottom-0 left-0 w-72 h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-[blob-bl_20s_linear_infinite]"></div>
                <div className="absolute bottom-0 right-0 w-72 h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-[blob-br_20s_linear_infinite]"></div>
                <div className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 w-96 h-96 bg-yellow-300 rounded-full mix-blend-multiply filter blur-xl opacity-50 animate-pulse"></div>
            </div>

            <div className="relative z-10 flex flex-col items-center p-2 sm:p-6 max-w-4xl mx-auto">
                <div className="bg-white/80 backdrop-blur-sm rounded-2xl shadow-xl p-4 sm:p-8 w-full" style={{border: '3px solid black'}}>
                    <div className="flex justify-center items-center gap-4 mb-6">
                        <h1 className="text-3xl font-bold text-black">BST Traversal Game</h1>
                        <button onClick={() => setShowModal(true)} className="p-2 text-2xl hover:bg-indigo-100 rounded">
                            ℹ️
                        </button>
                    </div>

                    {showModal && (
                        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
                            <div className="bg-white p-8 rounded-2xl max-w-[500px] w-[90%]">
                                <h2 className="text-2xl mb-5 text-indigo-900 text-center font-bold">How to Play</h2>
                                <div className="flex items-center gap-2.5 mb-4">
                                    <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">1</span>
                                    <p style={{textAlign:'left'}} className="text-black">The game displays a binary search tree (BST) structure.</p>
                                </div>
                                <div className="flex items-center gap-2.5 mb-4">
                                    <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">2</span>
                                    <p style={{textAlign:'left'}} className="text-black">Select a traversal method: In-order, Pre-order, or Post-order.</p>
                                </div>
                                <div className="flex items-center gap-2.5 mb-4">
                                    <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">3</span>
                                    <p style={{textAlign:'left'}} className="text-black">The game will show a number from the selected traversal.</p>
                                </div>
                                <div className="flex items-center gap-2.5 mb-4">
                                    <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">4</span>
                                    <p style={{textAlign:'left'}} className="text-black">Guess what the next number is in the traversal order.</p>
                                </div>
                                <div className="flex items-center gap-2.5 mb-4">
                                    <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">5</span>
                                    <p style={{textAlign:'left'}} className="text-black">Check your answer by pressing Enter or clicking the Check button.</p>
                                </div>
                                <div className="flex items-center gap-2.5 mb-4">
                                    <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">6</span>
                                    <p style={{textAlign:'left'}} className="text-black">If your guess is correct, you earn points!</p>
                                </div>
                                <button
                                    onClick={() => setShowModal(false)}
                                    className="w-full h-12 bg-indigo-900 text-white text-base font-semibold rounded-lg cursor-pointer flex justify-center items-center mt-8 transition-all duration-300 hover:bg-indigo-800"
                                >
                                    Close
                                </button>
                            </div>
                        </div>
                    )}

                    <div className="flex flex-col items-center gap-4 mb-4">
                        <select 
                            className="w-64 text-lg p-2 border-2 border-blue-500 rounded-lg text-black"
                            onChange={(e) => setTraversalMethod(e.target.value)} 
                            value={traversalMethod}
                        >
                            <option value="In-order">In-order</option>
                            <option value="Pre-order">Pre-order</option>
                            <option value="Post-order">Post-order</option>
                        </select>
                    </div>

                    <div className="flex justify-center items-center gap-7 mb-6">
                        <h2 className="text-xl font-bold text-black">Score: {score}</h2>
                        <span className="text-red-500 text-xl">❤️ {lives}</span>
                    </div>

                    <div className="overflow-x-auto">
                        <svg width="100%" height="275" viewBox="0 0 800 350" preserveAspectRatio="xMidYMid meet">
                            {renderTree(bst, 400, 40, 150)}
                        </svg>
                    </div>

                    <div className="text-center mt-6">
                        <h2 className="text-xl font-bold mb-2 text-black">Current number: {traversalValues[currentIndex]}</h2>
                        <p className="mb-4 text-black text-lg font-bold">What will be the next number?</p>
                        <div className="flex flex-col sm:flex-row justify-center items-center gap-4">
                            <input
                                ref={inputRef}
                                type="number"
                                className="text-lg p-2 border-2 border-blue-500 rounded-lg w-32 text-center text-black"
                                value={userInput}
                                onChange={(e) => setUserInput(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        e.preventDefault();
                                        handleGuess();
                                    }
                                }}
                            />
                            <button
                                onClick={handleGuess}
                                className="text-lg px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors w-full sm:w-auto"
                            >
                                Check
                            </button>
                        </div>
                    </div>
                </div>
            </div>
            <style jsx>{`
                @keyframes blob-tl {
                    0% { transform: translate(0, 0) scale(1); }
                    25% { transform: translate(calc(100vw - 18rem), 0) scale(1.1); }
                    50% { transform: translate(calc(100vw - 18rem), calc(100vh - 18rem)) scale(1); }
                    75% { transform: translate(0, calc(100vh - 18rem)) scale(0.9); }
                    100% { transform: translate(0, 0) scale(1); }
                }
                
                @keyframes blob-tr {
                    0% { transform: translate(0, 0) scale(1); }
                    25% { transform: translate(0, calc(100vh - 18rem)) scale(1.1); }
                    50% { transform: translate(calc(-100vw + 18rem), calc(100vh - 18rem)) scale(1); }
                    75% { transform: translate(calc(-100vw + 18rem), 0) scale(0.9); }
                    100% { transform: translate(0, 0) scale(1); }
                }
                
                @keyframes blob-br {
                    0% { transform: translate(0, 0) scale(1); }
                    25% { transform: translate(calc(-100vw + 18rem), 0) scale(1.1); }
                    50% { transform: translate(calc(-100vw + 18rem), calc(-100vh + 18rem)) scale(1); }
                    75% { transform: translate(0, calc(-100vh + 18rem)) scale(0.9); }
                    100% { transform: translate(0, 0) scale(1); }
                }
                
                @keyframes blob-bl {
                    0% { transform: translate(0, 0) scale(1); }
                    25% { transform: translate(0, calc(-100vh + 18rem)) scale(1.1); }
                    50% { transform: translate(calc(100vw - 18rem), calc(-100vh + 18rem)) scale(1); }
                    75% { transform: translate(calc(100vw - 18rem), 0) scale(0.9); }
                    100% { transform: translate(0, 0) scale(1); }
                }

                .animate-blob-tl {
                    animation: blob-tl 20s linear infinite;
                }
                
                .animate-blob-tr {
                    animation: blob-tr 20s linear infinite;
                }
                
                .animate-blob-bl {
                    animation: blob-bl 20s linear infinite;
                }
                
                .animate-blob-br {
                    animation: blob-br 20s linear infinite;
                }
                
                @keyframes pulse {
                    0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.5; }
                    50% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.3; }
                }

                @media (max-width: 640px) {
                    svg {
                        height: 300px;
                    }
                    
                    .bg-white\/80 {
                        padding: 1rem;
                    }
                    
                    h1 {
                        font-size: 1.5rem;
                    }
                    
                    select, input, button {
                        font-size: 1rem;
                    }
                }
            `}</style>
            <Navigation currentPage="bst-game" />
        </div>
    );
};

export default BstGame;