import React, { useState, useEffect } from 'react';
import Swal from 'sweetalert2';
import Navigation from '../Navigation';
import { Heart, Info } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const shuffleTree = (tree) => {
  const entries = Object.entries(tree);
  const shuffledEntries = [...entries].sort(() => Math.random() - 0.5);
  return Object.fromEntries(shuffledEntries);
};

const HuffmanGame = () => {
  const [lives, setLives] = useState(3);
  const [score, setScore] = useState(0);
  const [currentLevel, setCurrentLevel] = useState(0);
  const [userAnswer, setUserAnswer] = useState('');
  const [currentProblem, setCurrentProblem] = useState(null);
  const [gameOver, setGameOver] = useState(false);
  const navigate = useNavigate();
  const [showModal, setShowModal] = useState(false);
  
  const problems = [
    {
      level: 'Easy',
      huffmanTree: shuffleTree({
        '0': 'E',
        '10': 'A',
        '110': 'S',
        '111': 'T'
      }),
      encodedMessage: '010110111',
      solution: 'EAST',
      points: 50,
      verification: '0(E)10(A)110(S)111(T)'
    },
    {
      level: 'Easy',
      huffmanTree: shuffleTree({
        '0': 'H',
        '10': 'I',
        '110': 'T',
        '111': 'S'
      }),
      encodedMessage: '010110111',
      solution: 'HITS',
      points: 50,
      verification: '0(H)10(I)110(T)111(S)'
    },
    {
      level: 'Medium',
      huffmanTree: shuffleTree({
        '0': 'I',
        '10': 'N',
        '110': 'V',
        '111': 'A',
        '1110': 'D',
        '1111': 'E',
        '11111': 'R',
      }),
      encodedMessage: '0101101111110111111111',
      solution: 'INVADER',
      points: 100,
      verification: '0(I)10(N)110(V)111(A)1110(D)1111(E)11111(R)'
    },
    {
      level: 'Medium',
      huffmanTree: shuffleTree({
        '0': 'A',
        '10': 'L',
        '110': 'I',
        '111': 'E',
        '1110': 'N',
        '1111': 'S'
      }),
      encodedMessage: '01011011111101111',
      solution: 'ALIENS',
      points: 100,
      verification: '0(A)10(L)110(I)111(E)1110(N)1111(S)'
    },
    {
      level: 'Hard',
      huffmanTree: shuffleTree({
        '00': 'P',
        '01': 'L',
        '10': 'A',
        '110': 'N',
        '111': 'E',
        '1110': 'T',
        '1111': 'S'
      }),
      encodedMessage: '00011011011111101111',
      solution: 'PLANETS',
      points: 150,
      verification: '00(P)01(L)10(A)110(N)111(E)1110(T)1111(S)'
    },
    {
      level: 'Hard',
      huffmanTree: shuffleTree({
        '00': 'G',
        '01': 'A',
        '10': 'L',
        '110': 'X',
        '111': 'Y',
        '1110': 'I',
        '1111': 'E'
      }),
      encodedMessage: '00011001110111',
      solution: 'GALAXY',
      points: 150,
      verification: '00(G)01(A)10(L)110(X)111(Y)'
    }
  ];

  useEffect(() => {
    showIntroStory();
  }, []);

  const handleNavigation = (path) => {
    navigate(path);
};

  const showIntroStory = async () => {
    await Swal.fire({
      title: 'EMERGENCY ALERT!',
      html: `
        <div class="space-y-4">
          <p>🛸 Alien ships have been detected approaching Earth! 🌍</p>
          <p>They're transmitting encoded messages using Huffman coding.</p>
          <p>As Earth's top cryptographer, you must decode these messages before they reach our planet!</p>
          <p>You have 3 lives. Make them count! 🚀</p>
        </div>
      `,
      icon: 'warning',
      confirmButtonText: 'Accept Mission',
      allowOutsideClick: false,
      background: '#1a1a3a',
      color: '#fff',
      customClass: {
        popup: 'rounded-lg',
        title: 'text-red-600 font-bold',
        confirmButton: 'bg-blue-600 hover:bg-blue-700'
      }
    });
    const shuffledProblems = [...problems].sort(() => Math.random() - 0.5);
    setCurrentProblem(shuffledProblems[0]);
  };

  const handleWrongAnswer = async () => {
    const newLives = lives - 1;
    setLives(newLives);
    
    if (newLives === 0) {
      setGameOver(true);
      await Swal.fire({
        title: 'EARTH HAS FALLEN!',
        html: `
          <div class="relative">
            <p class="text-red-500 font-bold mb-4">The aliens have conquered Earth!</p>
            <p class="text-white">Final Score: ${score}</p>
            <p class="text-gray-300 mt-4">Maybe in another timeline, humanity will prevail...</p>
          </div>
        `,
        icon: 'error',
        confirmButtonText: 'Return to Base',
        background: '#1a1a3a',
        color: '#fff',
        customClass: {
          popup: 'rounded-lg space-y-4'
        }
      });
      handleNavigation('/ds');
      return;
    }

    await Swal.fire({
      title: 'Decoding Failed!',
      html: `
        <div class="relative">
          <p class="text-red-500">Warning: ${newLives} ${newLives === 1 ? 'life' : 'lives'} remaining!</p>
        </div>
      `,
      icon: 'error',
      timer: 2000,
      showConfirmButton: false,
      background: '#1a1a3a',
      color: '#fff'
    });
  };

  const checkAnswer = () => {
    if (userAnswer.toUpperCase() === currentProblem.solution) {
      handleCorrectAnswer();
    } else {
      handleWrongAnswer();
    }
  };

  const handleCorrectAnswer = async () => {
    setScore(score + currentProblem.points);
    if (currentLevel === problems.length - 1) {
      await victoryScreen();
    } else {
      await Swal.fire({
        title: 'Excellent Work!',
        html: `
          <p class="text-green-400">Message successfully decoded!</p>
          <p class="text-blue-400 mt-2">+${currentProblem.points} points</p>
        `,
        icon: 'success',
        timer: 2000,
        showConfirmButton: false,
        background: '#1a1a3a',
        color: '#fff'
      });
      const nextLevel = currentLevel + 1;
      setCurrentLevel(nextLevel);
      setCurrentProblem(problems[nextLevel]);
      setUserAnswer('');
    }
  };

  const victoryScreen = async () => {
    await Swal.fire({
      title: 'EARTH IS SAVED!',
      html: `
        <div class="space-y-4">
          <img src="/victory-earth.png" alt="Earth Saved" class="w-32 h-32 mx-auto mb-4"/>
          <p class="text-green-400">All alien messages decoded!</p>
          <p class="text-blue-400">Humanity is safe thanks to your cryptographic expertise.</p>
          <p class="text-white mt-4">Final Score: ${score + currentProblem.points}</p>
        </div>
      `,
      icon: 'success',
      confirmButtonText: 'Return to Base',
      background: '#1a1a3a',
      color: '#fff'
    });
    handleNavigation('/ds');
  };

  return (
    <div className="w-full min-h-screen bg-[#0a0a2a] relative overflow-hidden flex items-center justify-center">
      <div className="absolute inset-0 overflow-hidden">
        {/* Stars */}
        <div className="absolute inset-0">
          {[...Array(100)].map((_, i) => (
            <div
              key={i}
              className="absolute w-1 h-1 bg-white rounded-full animate-twinkle"
              style={{
                top: `${Math.random() * 100}%`,
                left: `${Math.random() * 100}%`,
                animationDelay: `${Math.random() * 3}s`
              }}
            />
          ))}
        </div>

        {/* Background gradients */}
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="w-full h-full bg-gradient-to-br from-purple-900/30 via-transparent to-blue-900/30 animate-pulse" />
          <div className="absolute w-3/4 h-3/4 bg-gradient-to-tr from-pink-900/20 via-transparent to-indigo-900/20 blur-xl animate-float-slow" />
        </div>

        {/* Red planet */}
        <div className="absolute top-20 right-40 w-24 h-24 rounded-full bg-gradient-to-br from-orange-500 to-red-800 shadow-lg animate-float-slow">
          <div className="absolute inset-0 rounded-full bg-gradient-to-t from-black/50 to-transparent" />
        </div>

          {/* Blue planet with synchronized rings */}
          <div className="absolute bottom-40 left-20 w-32 h-32 animate-float-medium">
            <div className="relative w-full h-full">
              {/* Planet */}
              <div className="absolute inset-0 rounded-full bg-gradient-to-br from-blue-500 to-purple-800 shadow-lg">
                <div className="absolute inset-0 rounded-full bg-gradient-to-t from-black/50 to-transparent" />
              </div>
              {/* Rings */}
              <div className="absolute inset-0 -rotate-12">
                <div className="absolute top-1/2 left-1/2 w-48 h-16 -translate-x-1/2 -translate-y-1/2">
                  <div className="absolute inset-0 w-full h-full rounded-full bg-black/20 blur-sm transform scale-105" />
                  <div className="w-full h-full bg-gradient-to-r from-transparent via-blue-300/40 to-transparent rounded-full transform scale-y-[0.2]" />
                  <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-purple-300/30 to-transparent rounded-full transform scale-y-[0.15] scale-x-95" />
                  <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-indigo-300/35 to-transparent rounded-full transform scale-y-[0.1] scale-x-90" />
                  {[...Array(8)].map((_, i) => (
                    <div
                      key={i}
                      className="absolute inset-0 w-full h-full rounded-full border border-white/5"
                      style={{
                        transform: `scale(${0.85 + i * 0.02}) scaleY(0.2)`,
                      }}
                    />
                  ))}
                  <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/10 to-transparent rounded-full transform scale-y-[0.18] scale-x-97" />
                </div>
              </div>
            </div>
          </div>

        {/* Meteors */}
        <div className="absolute w-full h-full">
          {[...Array(3)].map((_, i) => (
            <div
              key={i}
              className="absolute w-1 h-1 bg-white rounded-full"
              style={{
                top: `${Math.random() * 100}%`,
                left: `${Math.random() * 100}%`,
                boxShadow: '0 0 0 1px rgba(255,255,255,0.1), 0 0 3px rgba(255,255,255,0.1), 0 0 10px rgba(255,255,255,0.1)',
                transform: 'rotate(-45deg)',
              }}>
              <div className="w-12 h-[1px] bg-gradient-to-r from-white via-white to-transparent animate-meteor" />
            </div>
          ))}
        </div>
      </div>

      {/* Game Interface */}
      <div className="relative z-10 w-full max-w-4xl mx-auto p-4">
        <div className="bg-gray-900 bg-opacity-90 rounded-xl shadow-2xl p-6 border-2 border-blue-500">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4">
              <div className="flex gap-2">
                {[...Array(3)].map((_, i) => (
                  <Heart
                    key={i}
                    className={`w-8 h-8 ${i < lives ? 'text-red-500 fill-red-500' : 'text-gray-600'}`}
                  />
                ))}
              </div>
              <button 
                className="p-2 text-blue-400 hover:text-blue-300 transition-colors"
                onClick={() => setShowModal(true)}
              >
                <Info className="w-6 h-6" />
              </button>
            </div>
            <div className="flex flex-col items-end">
              <div className="text-blue-400 text-xl font-bold">
                Score: {score}
              </div>
              {currentProblem && (
                <div className={`text-sm ${
                  currentProblem.level === 'Easy' ? 'text-green-400' :
                  currentProblem.level === 'Medium' ? 'text-yellow-400' :
                  'text-red-400'
                }`}>
                  Level: {currentProblem.level}
                </div>
              )}
            </div>
          </div>

          {currentProblem && !gameOver && (
            <>
              <div className="mb-8 bg-gray-800 p-4 rounded-lg">
                <h3 className="text-blue-400 mb-4 font-bold">Huffman Code Reference:</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {Object.entries(currentProblem.huffmanTree).map(([code, char]) => (
                    <div key={code} className="flex items-center justify-between bg-gray-700 p-2 rounded">
                      <span className="text-green-400 font-mono">{code}:</span>
                      <span className="text-white font-bold">{char}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="mb-8">
                <h3 className="text-blue-400 mb-2 font-bold">Encoded Alien Message:</h3>
                <div className="bg-black p-4 rounded-lg">
                  <p className="text-green-400 font-mono text-lg break-all">
                    {currentProblem.encodedMessage}
                  </p>
                </div>
              </div>

              <div className="flex flex-col gap-4">
                <input
                  type="text"
                  value={userAnswer}
                  onChange={(e) => setUserAnswer(e.target.value)}
                  placeholder="Enter decoded message..."
                  className="w-full p-3 bg-gray-800 text-white rounded-lg border-2 border-blue-500 focus:outline-none focus:border-blue-600"
                  onKeyPress={(e) => e.key === 'Enter' && checkAnswer()}
                />
                <button
                  onClick={checkAnswer}
                  className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg transition-colors"
                >
                  Submit Decode Attempt
                </button>
              </div>
            </>
          )}
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm p-4">
          <div className="bg-gray-900 p-6 rounded-xl max-w-md w-full border-2 border-blue-500">
            <h2 className="text-2xl text-blue-400 font-bold mb-4">How to Play</h2>
            <div className="space-y-4 text-gray-300">
              <p>1. Each level presents you with a Huffman code table and an encoded message.</p>
              <p>2. Use the code table to decode the binary message into text.</p>
              <p>3. Type your answer and submit to check if it's correct.</p>
              <p>4. You have 3 lives - be careful not to lose them all!</p>
              <p>5. Different difficulty levels award different points:</p>
              <ul className="list-disc list-inside pl-4">
                <li className="text-green-400">Easy: 50 points</li>
                <li className="text-yellow-400">Medium: 100 points</li>
                <li className="text-red-400">Hard: 150 points</li>
              </ul>
            </div>
            <button
              onClick={() => setShowModal(false)}
              className="mt-6 w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
            >
              Got it!
            </button>
          </div>
        </div>
      )}

      <style jsx>{`
        @keyframes twinkle {
          0%, 100% { opacity: 0.2; transform: scale(0.8); }
          50% { opacity: 1; transform: scale(1); }
        }
        
        @keyframes float-slow {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-20px) rotate(3deg); }
        }
        
        @keyframes float-medium {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-15px) rotate(-3deg); }
        }
        
        @keyframes meteor {
          0% { transform: translateX(0); opacity: 1; }
          100% { transform: translateX(-200px); opacity: 0; }
        }
        
        .animate-twinkle { animation: twinkle 3s infinite; }
        .animate-float-slow { animation: float-slow 6s infinite; }
        .animate-float-medium { animation: float-medium 4s infinite; }
        .animate-meteor { animation: meteor 2s linear infinite; }
      `}</style>
      <Navigation currentPage="huffmangame" />
    </div>
  );
}

 export default HuffmanGame;

