import React, { useState, useEffect, useRef } from "react";
import { Maximize2, Minimize2, RotateCcw } from "lucide-react";
import "./huffman.css";
import huffman from "../Images/huffman.png";
import Navigation from "../Navigation";

const HuffmanVisualizer = () => {
  const [text, setText] = useState("");
  const [steps, setSteps] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isLandscape, setIsLandscape] = useState(false);
  const svgRef = useRef(null);
  const inputRef = useRef(null);
  const modalRef = useRef(null);

  useEffect(() => {
    const checkOrientation = () => {
      setIsLandscape(window.innerWidth > window.innerHeight);
    };

    window.addEventListener('resize', checkOrientation);
    checkOrientation();

    return () => window.removeEventListener('resize', checkOrientation);
  }, []);

  useEffect(() => {
    const handleKeyPress = (e) => {
      if (e.key === 'Enter' && document.activeElement === inputRef.current) {
        e.preventDefault();
        if (!showModal) {
          runAnimation();
        }
      } else if (e.key === 'ArrowRight' && steps.length > 0) {
        setCurrentStep((prev) => Math.min(prev + 1, steps.length - 1));
      } else if (e.key === 'ArrowLeft' && steps.length > 0) {
        setCurrentStep((prev) => Math.max(prev - 1, 0));
      } else if (e.key === 'Escape') {
        if (isFullScreen) {
          setIsFullScreen(false);
        } else if (showModal) {
          setShowModal(false);
        }
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, [steps.length, showModal, isFullScreen]);

  useEffect(() => {
    if (!showModal) {
      inputRef.current?.focus();
    } else {
      modalRef.current?.focus();
    }
  }, [showModal]);

  const generateFrequencyMap = (text) => {
    const freqMap = {};
    for (let char of text) {
      freqMap[char] = (freqMap[char] || 0) + 1;
    }
    return freqMap;
  };

  const buildHuffmanTreeStepByStep = (freqMap) => {
    let nodes = Object.entries(freqMap).map(([char, freq]) => ({
      char,
      freq,
    }));
    const stepsCurr = [];

    nodes.sort((a, b) => a.freq - b.freq);
    
    stepsCurr.push({
      queue: nodes.map((node) => 
        node.char ? `${node.char} : ${node.freq}` : `${renderTree(node.left)}${renderTree(node.right)}`
      ),
      tree: null,
    });

    while (nodes.length > 1) {
      nodes.sort((a, b) => a.freq - b.freq);
      const left = nodes.shift();
      const right = nodes.shift();
      const newNode = {
        freq: left.freq + right.freq,
        left,
        right,
      };
      nodes.push(newNode);
      stepsCurr.push({
        queue: nodes.map((node) =>
          node.char
            ? `${node.char} : ${node.freq}`
            : `${renderTree(node.left)}${renderTree(node.right)} : ${node.freq}`
        ),
        tree: newNode,
      });
    }

    setSteps(stepsCurr);
  };

  const renderTree = (node) => {
    if (!node) return "";
    if (node.char) return node.char;
    return `${renderTree(node.left)}${renderTree(node.right)}`;
  };

  const renderHuffmanTree = (node, x, y, dx) => {
    if (!node) return null;
    const levelHeight = 80;
    const nodeRadius = 20;

    return (
      <g key={`${node.char || "internal"}-${node.freq}`}>
        {node.left && (
          <line
          x1={x - nodeRadius * Math.cos(Math.PI / 8)} 
          y1={y + nodeRadius * Math.sin(Math.PI / 8)} 
          x2={x - dx * 0.8} 
          y2={y + levelHeight - nodeRadius * 0.8} 
          className="stroke-black stroke-2"
          />
        )}
        {node.right && (
          <line 
          x1={x + nodeRadius * Math.cos(Math.PI / 8)} 
          y1={y + nodeRadius * Math.sin(Math.PI / 8)} 
          x2={x + dx * 0.8} 
          y2={y + levelHeight - nodeRadius * 0.8} 
          className="stroke-black stroke-2"
          />
        )}
        <circle cx={x} cy={y} r={nodeRadius} className="fill-white stroke-black stroke-2 cursor-pointer" />
        <text
          x={x}
          y={y}
          textAnchor="middle"
          fill="#000"
          fontSize="14"
          dy=".3em"
        >
          {node.char || `${node.freq}`}
        </text>
        {node.left && renderHuffmanTree(node.left, x - dx, y + levelHeight, dx / 1.5)}
        {node.right && renderHuffmanTree(node.right, x + dx, y + levelHeight, dx / 1.5)}
      </g>
    );
  };

  const generateHuffmanCodes = (tree, prefix = "", codes = []) => {
    if (!tree) return codes;
    if (tree.char) {
      codes.push({ char: tree.char, code: prefix });
    } else {
      generateHuffmanCodes(tree.left, prefix + "0", codes);
      generateHuffmanCodes(tree.right, prefix + "1", codes);
    }
    return codes;
  };

  const renderQueue = (nodes) => {
    return (
      <div className="flex flex-wrap justify-center gap-2">
        {nodes.map((node, index) => (
          <div key={index} className="bg-blue-200 px-3 py-1.5 border border-black rounded-md text-sm md:text-base">
            {node}
          </div>
        ))}
      </div>
    );
  };

  const runAnimation = () => {
    if (!text) return;
    const freqMap = generateFrequencyMap(text);
    buildHuffmanTreeStepByStep(freqMap);
    setCurrentStep(0);
  };

  const handleLandscapeMode = () => {
    const orientation = window.matchMedia("(orientation: landscape)");
    if (orientation?.matches) {
      setIsFullScreen(true);
    } else {
      window.alert("Please rotate your device to landscape mode for a better view");
    }
  };

  return (
    <div className="flex flex-col gap-4 px-2 md:px-5 min-h-screen bg-[#f0f4f8] text-black">
      <div className="flex justify-center items-center gap-4 mt-4">
        <h1 className="text-xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent">
          Huffman Tree Visualizer
        </h1>
        <button 
          className="text-xl md:text-2xl text-indigo-900 hover:bg-indigo-100 rounded p-1"
          onClick={() => setShowModal(true)}
        >
          ℹ️
        </button>
      </div>

      <div className="flex-grow">
        <div className={`grid gap-4 ${
          isFullScreen || window.innerWidth <= 768 
            ? 'grid-cols-1' 
            : 'grid-cols-[360px_1fr]'
        }`}>
          {!isFullScreen && (
            <div className="flex flex-col bg-white rounded-lg p-4 shadow-md h-[650px] overflow-y-auto">
              <div
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    runAnimation();
                  }
                }}
              >
                <input
                  ref={inputRef}
                  type="text"
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  placeholder="Enter text and press Enter"
                  className="p-2 text-base md:text-lg border border-gray-400 rounded-lg focus:ring-2 focus:ring-blue-400 focus:outline-none mb-4 w-full"
                />
                <button
                  onClick={(e) => {
                    e.preventDefault();
                    runAnimation();
                  }}
                  className="w-full px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  Generate Tree
                </button>
              </div>

              {steps[currentStep]?.queue && (
                <div className="mt-4">
                  <div className="bg-blue-950 p-3 rounded-lg">
                    {renderQueue(steps[currentStep].queue)}
                  </div>
                  
                  <div className="flex justify-center gap-2 mt-4">
                    <button
                      onClick={() => setCurrentStep(prev => Math.max(prev - 1, 0))}
                      disabled={currentStep === 0}
                      className="px-3 py-1.5 bg-blue-600 text-white rounded-lg disabled:bg-gray-300 hover:bg-blue-700 transition-colors text-sm md:text-base"
                    >
                      ← Previous
                    </button>
                    <button
                      onClick={() => setCurrentStep(prev => Math.min(prev + 1, steps.length - 1))}
                      disabled={currentStep === steps.length - 1}
                      className="px-3 py-1.5 bg-blue-600 text-white rounded-lg disabled:bg-gray-300 hover:bg-blue-700 transition-colors text-sm md:text-base"
                    >
                      Next →
                    </button>
                  </div>
                </div>
              )}

              {steps[steps.length - 1]?.tree && (
                <div className="mt-4 overflow-x-auto">
                  <table className="w-full border-collapse bg-amber-300">
                    <thead>
                      <tr>
                        <th className="border-2 px-4 py-2 text-lg" colSpan="2">
                          Huffman Codes
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {generateHuffmanCodes(steps[steps.length - 1].tree).map((item, index) => (
                        <tr key={index}>
                          <td className="border-2 px-4 py-1 w-1/2">{item.char}</td>
                          <td className="border-2 px-4 py-1 w-1/2 font-mono">{item.code}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          <div className={`bg-white rounded-lg p-4 shadow-md relative ${
            window.innerWidth <= 768 && !isLandscape ? 'h-[400px]' : 'h-[650px]'
          }`}>
            {steps[currentStep]?.tree ? (
              <>
                <div className="absolute top-4 right-4 flex gap-2">
                  {window.innerWidth <= 768 && (
                    <button
                      onClick={handleLandscapeMode}
                      className="p-1 text-gray-600 hover:text-gray-800 transition-colors"
                      title="Rotate to Landscape"
                    >
                      <RotateCcw className="w-6 h-6" />
                    </button>
                  )}
                  <button
                    onClick={() => setIsFullScreen(!isFullScreen)}
                    className="p-1 text-gray-600 hover:text-gray-800 transition-colors"
                    title={isFullScreen ? "Exit Fullscreen" : "Enter Fullscreen"}
                  >
                    {isFullScreen ? <Minimize2 className="w-6 h-6" /> : <Maximize2 className="w-6 h-6" />}
                  </button>
                </div>
                <svg 
                  className="w-full h-full border rounded-lg"
                  ref={svgRef}
                  viewBox={window.innerWidth <= 768 ? "0 0 900 600" : undefined}
                  preserveAspectRatio="xMidYMid meet"
                >
                  {renderHuffmanTree(
                    steps[currentStep].tree,
                    svgRef.current?.clientWidth / 2 || 450,
                    30,
                    window.innerWidth <= 768 ? 150 : 200
                  )}
                </svg>
              </>
            ) : (
              <div className="flex flex-col md:flex-row items-center justify-center h-full gap-6 p-4">
                <img src={huffman} alt="Huffman Tree" className="w-48 h-48 md:w-72 md:h-72 object-contain" />
                <div className="flex flex-col gap-4 max-w-md">
                  <h2 className="text-xl md:text-2xl font-bold text-indigo-900">
                    Start Building Your Huffman Tree!
                  </h2>
                  <p className="text-gray-600 text-sm md:text-base">
                    Enter your text and press Enter or click the Generate Tree button to start. 
                    Use the Previous and Next buttons or arrow keys to navigate through the tree building process.
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
          <div className="bg-white p-8 rounded-2xl max-w-[600px] w-[90%]">
            <h2 className="text-2xl mb-5 text-indigo-900 text-center font-bold">
              How to Use Huffman Tree Visualization
            </h2>
            <div className="space-y-4">
              {[
                "Enter your text in the input field. This will be used to generate the Huffman tree.",
                "Click 'Generate Tree' or press Enter to start the visualization process.",
                "The queue on the left shows the nodes being processed, with their frequencies.",
                "The tree visualization on the right shows how nodes are combined to form the final Huffman tree.",
                "Once complete, you'll see a table showing the Huffman codes for each character.",
                "For mobile users, rotate your device or use the rotate button for a better landscape view."
              ].map((text, index) => (
                <div key={index} className="flex items-start gap-2.5">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold mt-0.5">
                    {index + 1}
                  </span>
                  <p className="text-gray-700 text-left">{text}</p>
                </div>
              ))}
            </div>
            <div className="mt-6 p-4 bg-blue-50 rounded-lg">
              <h3 className="text-lg font-semibold text-indigo-900 mb-2">Keyboard Shortcuts</h3>
              <ul className="space-y-2 text-gray-700">
                <li>• Enter - Generate tree or close modal</li>
                <li>• ← Left Arrow - Previous step</li>
                <li>• → Right Arrow - Next step</li>
                <li>• Esc - Exit fullscreen / Close modal</li>
              </ul>
            </div>
            <button 
              onClick={() => setShowModal(false)} 
              className="w-full h-12 bg-indigo-900 text-white text-base font-semibold rounded-lg mt-8 hover:bg-indigo-800 transition-colors flex justify-center items-center"
            >
              Close
            </button>
          </div>
        </div>
      )}
      <Navigation currentPage="huffman-learn" />
    </div>
  );
};

export default HuffmanVisualizer;