import React, { useState, useRef } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import Navigation from "../Navigation";
import {
  linearHashingCode,
  quadraticProbingCode,
  chainingCode,
} from "./hashingCodes";

const HashingVisualization = () => {
  const [table, setTable] = useState(new Array(10).fill(null));
  const [inputValue, setInputValue] = useState("");
  const [message, setMessage] = useState("");
  const [selectedLanguage, setSelectedLanguage] = useState("pseudo");
  const [activeSection, setActiveSection] = useState("learn");
  const [activeLearningPage, setActiveLearningPage] = useState(1);
  const [showHowToUseModal, setShowHowToUseModal] = useState(false);
  const [hashMethod, setHashMethod] = useState("linear");
  const inputRef = useRef(null);

  const methodCode = (method) => {
    switch (method) {
      case "linear":
        return linearHashingCode;
      case "quadratic":
        return quadraticProbingCode;
      case "chaining":
        return chainingCode;
      default:
        return linearHashingCode;
    }
  };

  const HowToUseModal = () => (
    showHowToUseModal && (
      <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
        <div className="bg-white p-6 rounded-2xl w-full max-w-md max-h-[600px] flex flex-col">
          <h2 className="text-2xl mb-4 text-indigo-900 text-center font-bold">
            How to Use Hashing Visualization
          </h2>
          <div className="overflow-y-auto pr-3">
            <div className="space-y-3">
              {[
                "Enter a number between 1 and 999 in the input field.",
                "Choose a hash method: Linear Probing, Quadratic Probing, or Chaining.",
                "Click 'Insert' to add the number to the hash table.",
                "Click 'Delete' to remove a number from the table.",
                "Click 'Search' to find a number in the table."
              ].map((text, index) => (
                <div key={index} className="flex items-start gap-2.5">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">
                    {index + 1}
                  </span>
                  <p className="text-gray-700">{text}</p>
                </div>
              ))}
            </div>
            
            <div className="mt-4 p-3 bg-blue-50 rounded-lg">
              <h3 className="text-lg font-bold text-indigo-900 mb-2">Keyboard Shortcuts</h3>
              <ul className="space-y-2 text-gray-700">
                <li>• <strong>Enter</strong> - Insert number</li>
                <li>• <strong>Delete</strong> - Delete number</li>
                <li>• <strong>Esc</strong> - Close modal</li>
              </ul>
            </div>
          </div>
          <button 
            onClick={() => setShowHowToUseModal(false)}
            className="w-full h-12 bg-indigo-900 text-white font-semibold rounded-lg mt-4 hover:bg-indigo-800"
          >
            Close
          </button>
        </div>
      </div>
    )
  );

  const handleInputChange = (e) => {
    const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 3);
    setInputValue(value);
    setMessage("");
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') insert();
    else if (e.key === 'Delete') deleteItem();
  };

  const handleSizeChange = (e) => {
    const newSize = parseInt(e.target.value);
    if (newSize >= 1 && newSize <= 100) {
      setTable(new Array(newSize).fill(null));
      setMessage(`Table size updated to ${newSize}`);
    } else {
      setMessage("Table size must be between 1 and 100");
    }
  };

  const hashFunction = (key) => key % table.length;

  const insert = () => {
    const value = parseInt(inputValue);
    if (isNaN(value) || value < 1 || value > 999) {
      setMessage("Please enter a number between 1 and 999");
      return;
    }

    const key = hashFunction(value);
    const newTable = [...table];

    if (hashMethod === "linear") {
      let index = key;
      while (newTable[index] !== null) {
        index = (index + 1) % table.length;
        if (index === key) {
          setMessage("Table is full");
          return;
        }
      }
      newTable[index] = value;
    } else if (hashMethod === "quadratic") {
      let i = 0;
      let index = key;
      while (newTable[index] !== null) {
        i++;
        index = (key + i * i) % table.length;
        if (i >= table.length) {
          setMessage("Cannot find empty slot");
          return;
        }
      }
      newTable[index] = value;
    } else if (hashMethod === "chaining") {
      if (!newTable[key]) newTable[key] = [];
      newTable[key].push(value);
    }

    setTable(newTable);
    setInputValue("");
    setMessage(`${value} inserted successfully`);
    inputRef.current?.focus();
  };

  const deleteItem = () => {
    const value = parseInt(inputValue);
    if (isNaN(value)) {
      setMessage("Please enter a valid number");
      return;
    }

    const key = hashFunction(value);
    const newTable = [...table];
    let found = false;

    if (hashMethod === "chaining") {
      if (newTable[key]) {
        const index = newTable[key].indexOf(value);
        if (index !== -1) {
          newTable[key].splice(index, 1);
          found = true;
        }
      }
    } else {
      let index = key;
      while (newTable[index] !== null) {
        if (newTable[index] === value) {
          newTable[index] = null;
          found = true;
          break;
        }
        index = hashMethod === "linear" 
          ? (index + 1) % table.length 
          : (key + Math.pow(index - key + 1, 2)) % table.length;
        if (index === key) break;
      }
    }

    if (found) {
      setTable(newTable);
      setMessage(`${value} deleted successfully`);
    } else {
      setMessage(`${value} not found in table`);
    }
    setInputValue("");
    inputRef.current?.focus();
  };

  const search = () => {
    const value = parseInt(inputValue);
    if (isNaN(value)) {
      setMessage("Please enter a valid number");
      return;
    }

    const key = hashFunction(value);
    let found = false;
    let foundIndex = -1;

    if (hashMethod === "chaining") {
      if (table[key] && table[key].includes(value)) {
        found = true;
        foundIndex = key;
      }
    } else {
      let index = key;
      while (table[index] !== null) {
        if (table[index] === value) {
          found = true;
          foundIndex = index;
          break;
        }
        index = hashMethod === "linear" 
          ? (index + 1) % table.length 
          : (key + Math.pow(index - key + 1, 2)) % table.length;
        if (index === key) break;
      }
    }

    setMessage(found ? `Found ${value} at index ${foundIndex}` : `${value} not found in table`);
    setInputValue("");
    inputRef.current?.focus();
  };

  const togglePage = (direction) => {
    if (direction === 'next' && activeLearningPage < learningPages.length) {
      setActiveLearningPage(prev => prev + 1);
    } else if (direction === 'prev' && activeLearningPage > 1) {
      setActiveLearningPage(prev => prev - 1);
    }
  };

  const learningPages = [
    {
      content: (
        <div className="space-y-4 text-slate-700 flex flex-col justify-center items-center">
          <h2 className="flex text-2xl font-bold text-indigo-900 mb-6 justify-center">What is a Hashing?</h2>
          <p>
            Hashing is a technique used to map data to a specific index in a hash table 
            using a hash function, enabling efficient data retrieval and storage.
          </p>

          <h3 className="text-xl font-bold text-indigo-800 mt-4">Key Concepts</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li>
              <strong>Hash Function:</strong> Converts input to a specific index
            </li>
            <li>
              <strong>Collision:</strong> When multiple elements map to the same index
            </li>
            <li>
              <strong>Probing:</strong> Techniques to resolve collisions
            </li>
            <li>
              <strong>Load Factor:</strong> Ratio of occupied slots to total table size
            </li>
          </ul><br/>

          <div className="mt-6 bg-slate-100 rounded-xl p-4 flex justify-center items-center w-[80%]">
            <div className="flex flex-row gap-2">
              {[42, 17, 88].map((num, index) => (
                <div 
                  key={index} 
                  className="w-12 h-12 bg-white border-2 border-indigo-300 rounded-lg flex items-center justify-center text-lg font-bold"
                >
                  {num}
                </div>
              ))}
            </div>
            <div className="ml-4 text-slate-600 text-sm">
              <div>Hash Function Maps Values</div>
              <div>to Specific Indices</div>
            </div>
          </div>
        </div>
      )
    },
    {
      content: (
        <div className="space-y-4 text-slate-700 flex flex-col justify-center items-center">
          <h3 className="text-xl font-bold text-indigo-800" style={{textAlign:'center', fontSize:'24px'}}>Hashing Techniques</h3>
          <ul className="list-disc pl-6 space-y-3">
            <li>
              <strong>Linear Probing:</strong> Next open slot when collision occurs
            </li>
            <li>
              <strong>Quadratic Probing:</strong> Squares of offsets to find next slot
            </li>
            <li>
              <strong>Chaining:</strong> Linked lists at each index for multiple values
            </li>
          </ul><br/>

          <div className="space-y-4 text-slate-700">
            <h3 className="text-xl font-bold text-indigo-800" style={{textAlign:'center', fontSize:'24px'}}>Where Hashing is Used</h3>
            <ul className="list-disc pl-6 space-y-3">
              <li>
                <strong>Database Indexing:</strong> Quick data retrieval
              </li>
              <li>
                <strong>Caching:</strong> Fast data access
              </li>
              <li>
                <strong>Cryptography:</strong> Data encryption
              </li>
              <li>
                <strong>Symbol Tables:</strong> Compiler implementations
              </li>
              <li>
                <strong>Password Storage:</strong> Secure authentication
              </li>
            </ul>
          </div>
        </div>
      )
    }
  ];

  const renderContent = () => {
    switch (activeSection) {
      case "learn":
        return renderLearningContent();
      case "visualization":
        return renderVisualizationContent();
      case "implementation":
        return renderImplementationContent();
      default:
        return null;
    }
  };

  const renderLearningContent = () => {
    const currentPage = learningPages[activeLearningPage - 1];
    return (
      <div className="flex-grow p-4 flex flex-col overflow-y-auto">
        <div className="flex-grow">
          <h3 className="text-2xl font-bold text-indigo-800 mb-4">
            {currentPage.title}
          </h3>
          {currentPage.content}
        </div>
        
        <div className="flex justify-center items-center gap-4 mt-6">
          <button 
            onClick={() => togglePage('prev')} 
            disabled={activeLearningPage === 1}
            className={`p-2 rounded-full ${activeLearningPage === 1 ? 'bg-slate-200' : 'bg-indigo-100 hover:bg-indigo-200'}`}
          >
            <ChevronLeft className={`w-6 h-6 ${activeLearningPage === 1 ? 'text-slate-400' : 'text-indigo-800'}`} />
          </button>
          <span className="text-slate-600">
            Page {activeLearningPage} of {learningPages.length}
          </span>
          <button 
            onClick={() => togglePage('next')} 
            disabled={activeLearningPage === learningPages.length}
            className={`p-2 rounded-full ${activeLearningPage === learningPages.length ? 'bg-slate-200' : 'bg-indigo-100 hover:bg-indigo-200'}`}
          >
            <ChevronRight className={`w-6 h-6 ${activeLearningPage === learningPages.length ? 'text-slate-400' : 'text-indigo-800'}`} />
          </button>
        </div>
      </div>
    );
  };

  const renderVisualizationContent = () => (
    <div className="flex-grow p-4 overflow-y-auto">
      <div className="flex justify-center items-center gap-4">
        <h1 className="text-xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent">
          Hash Table Visualization
        </h1>
        <button 
          className="text-xl md:text-2xl text-indigo-900 hover:bg-indigo-100 rounded p-1"
          onClick={() => setShowHowToUseModal(true)}
        >
          ℹ️
        </button>
      </div>

      <div className="bg-slate-50 rounded-xl border-2 border-slate-200 shadow-inner mb-6 h-60 m-5 overflow-y-auto">
          <div className="h-80 p-4">
            <div className="flex flex-col items-center gap-2">
            {table.map((item, index) => (
                <div key={index} className="flex items-center w-[80%] pb-2 h-12">
                  <div className="w-16 text-center text-gray-600 font-medium">
                    {index}
                  </div>
                  <div
                    className="flex-grow py-2 px-4 rounded-md text-black min-h-[3rem] flex items-center font-bold justify-center"
                    style={{
                      backgroundColor: `hsl(${200 + index * 15}, 75%, 65%)`,
                    }}
                  >
                    {item ? (Array.isArray(item) ? item.join(", ") : item) : ""}
                  </div>
                </div>
              ))}
          </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row items-center justify-center gap-3 mb-4">
          <label className="text-slate-600 font-medium">Table Size:</label>
          <input 
            type="number"
            min="1"
            max="100"
            value={table.length}
            onChange={handleSizeChange}
            className="w-20 p-2 rounded-lg border-2 border-slate-300 text-center text-black"
          />

          <label className="text-slate-600 font-medium ml-4">Hash Method:</label>
          <select
            value={hashMethod}
            onChange={(e) => {
              setHashMethod(e.target.value);
              setTable(new Array(table.length).fill(null));
            }}
            className="p-2 rounded-lg border-2 border-slate-300 text-black"
          >
            <option value="linear">Linear Probing</option>
            <option value="quadratic">Quadratic Probing</option>
            <option value="chaining">Chaining</option>
          </select>
        </div>

      <div className="space-y-4 px-4">
        <div className="flex flex-col md:flex-row gap-4">
          <input
            type="text"
            value={inputValue}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            ref={inputRef}
            placeholder="Enter value (1-999)"
            className="flex-1 p-3.5 rounded-lg border-2 border-slate-300"
          />
          <button
            onClick={insert}
            className="md:w-32 px-7 py-3.5 rounded-lg text-white font-semibold bg-blue-500 hover:bg-blue-600 transition-colors"
          >
            Insert
          </button>
        </div>
        
        <div className="flex justify-center gap-4">
          <button
            onClick={deleteItem}
            className="px-7 py-3.5 rounded-lg text-white font-semibold bg-emerald-500 hover:bg-emerald-600 transition-colors w-32"
          >
            Delete
          </button>
          <button
            onClick={search}
            className="px-7 py-3.5 rounded-lg text-white font-semibold bg-red-500 hover:bg-red-600 transition-colors w-32"
          >
            Search
          </button>
        </div>
      </div>

      {message && (
          <div className={`mt-5 p-3.5 rounded-lg text-base font-semibold text-center
            ${message.includes("between") || message.includes("Not found") || message.includes("full")
              ? "bg-red-100 text-red-600"
              : "bg-green-100 text-green-600"
            }`}
          >
            {message}
        </div>
      )}
    </div>
  );

  const renderImplementationContent = () => (
    <div className="flex-grow p-6 overflow-y-auto">
      <h2 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent text-center mb-6">
        Hash Table Implementation
      </h2>
  
      <div className="grid md:grid-cols-2 gap-4 mb-6">
        <div className="space-y-2">
          <label className="block text-sm font-medium text-gray-700">
            Select Language
          </label>
          <select
            value={selectedLanguage}
            onChange={(e) => setSelectedLanguage(e.target.value)}
            className="w-full p-3 rounded-lg border-2 border-slate-200 bg-white hover:border-indigo-500 transition-colors"
          >
            <option value="pseudo">Pseudocode</option>
            <option value="cpp">C++</option>
            <option value="c">C</option>
            <option value="python">Python</option>
            <option value="java">Java</option>
          </select>
        </div>
  
        <div className="space-y-2">
          <label className="block text-sm font-medium text-gray-700">
            Select Hashing Method
          </label>
          <select
            value={hashMethod}
            onChange={(e) => setHashMethod(e.target.value)}
            className="w-full p-3 rounded-lg border-2 border-slate-200 bg-white hover:border-indigo-500 transition-colors"
          >
            <option value="linear">Linear Probing</option>
            <option value="quadratic">Quadratic Probing</option>
            <option value="chaining">Chaining</option>
          </select>
        </div>
      </div>
  
      <pre className="bg-gray-900 text-white p-6 overflow-auto rounded-xl leading-relaxed min-h-[500px]">
        <code
          className="block font-mono text-sm md:text-base"
          dangerouslySetInnerHTML={{
            __html: methodCode(hashMethod)[selectedLanguage],
          }}
        />
      </pre>
  
      <div className="mt-6 p-4 bg-blue-50 rounded-lg border border-blue-100">
        <h3 className="text-lg font-bold text-indigo-900 mb-2">
          Implementation Notes
        </h3>
        <ul className="space-y-2 text-gray-700">
          <li className="flex items-start gap-2">
            <span className="text-indigo-500">•</span>
            <strong>Time Complexity:</strong> {hashMethod === 'chaining' ? 'O(1) average case' : 'O(1) best case, O(n) worst case'}
          </li>
          <li className="flex items-start gap-2">
            <span className="text-indigo-500">•</span>
            <strong>Space Complexity:</strong> O(n)
          </li>
          <li className="flex items-start gap-2">
            <span className="text-indigo-500">•</span>
            <strong>Best used when:</strong> {
              hashMethod === 'linear' ? 'Load factor is low and cache performance is important' :
              hashMethod === 'quadratic' ? 'Medium load factor and clustering needs to be minimized' :
              'High load factor and memory is not a constraint'
            }
          </li>
        </ul>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col w-full gap-6 p-4 bg-gradient-to-br from-blue-50 to-blue-100 min-h-screen">
      <div className="relative w-full transition-all duration-300 ease-in-out h-[700px] bg-white rounded-2xl shadow-lg p-0 flex flex-col">
        <div className="flex p-0 justify-around items-center border-b-2 h-[8vh] z-50">
          <div 
            onClick={() => setActiveSection("learn")}
            className={`w-1/3 text-center border-r-2 h-[50px] flex items-center justify-center cursor-pointer 
              ${activeSection === "learn" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Learn
          </div>
          
          <div 
            onClick={() => setActiveSection("visualization")}
            className={`w-1/3 text-center border-r-2 h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "visualization" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Visualize
          </div>

          <div 
            onClick={() => setActiveSection("implementation")}
            className={`w-1/3 text-center h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "implementation" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Code
          </div>
        </div>

        {renderContent()}
      </div>
      
      <Navigation currentPage="hash-table-learn" />
      {HowToUseModal()}
    </div>
  );
};

export default HashingVisualization;