import React from "react";
import { BrowserRouter, Route, Routes, Navigate } from "react-router-dom";
import LinkedList from "./Learn/LinkedList";
import Stacks from "./Learn/Stacks";
import BSTApp from "./Algorithms/bst";
import Bstgame from "./Game/bstgame";
import Water from "./Game/water";
import HuffmanVisualizer from "./Learn/huffman";
import Dashboard from "./Dashboard/dashboard";
import QueueGame from "./Game/queuegame";
import LinkedlistGame from "./Game/llgame";
import Hashing from "./Learn/Hashing";
import BST from "./Learn/bst";
import AlgorithmsPage from "./Homepages/Algorithm_home";
import HashTableGame from "./Game/HashTableGame";
import HuffmanGame from "./Game/Huffgame";
import QueueVisualization from "./Learn/Queues";
import HomePage from "./Homepages/Home";
import DataStructures from './Homepages/DataStructures';

const App = () => {
  const getBasename = () => {
    const hostname = window.location.hostname;
    const path = window.location.pathname;
    
    if (hostname === "jia2005.github.io") {
      return "/Algorific";
    }
  
    if (hostname.includes('vercel.app') && path.startsWith('/Algorific/')) {
      return "/Algorific";
    }
    
    return "/";
  };

  const basename = getBasename();

  return (
    <BrowserRouter basename={basename}>
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/ds" element={<DataStructures />} />
        <Route path="/home" element={<HomePage />} />
        <Route path="/linkedlist" element={<LinkedList />} />
        <Route path="/stack" element={<Stacks />} />
        <Route path="/queue" element={<QueueVisualization />} />
        <Route path="/bstalgo" element={<BSTApp />} />
        <Route path="/bstgame" element={<Bstgame />} />
        <Route path="/water" element={<Water />} />
        <Route path="/huffman" element={<HuffmanVisualizer />} />
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/queuegame" element={<QueueGame />} />
        <Route path="/ll-game" element={<LinkedlistGame />} />
        <Route path="/hashlearn" element={<Hashing />} />
        <Route path="/bst" element={<BST />} />
        <Route path="/algohome" element={<AlgorithmsPage />} />
        <Route path="/hashing-game" element={<HashTableGame />} />
        <Route path="/huffmangame" element={<HuffmanGame />} />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </BrowserRouter>
  );
};

export default App;